const RENTRACK_SCRIPT = "<script>\n/* Renaud featured tracking.\n * Companion to the existing v5.5 GoatCounter action events script.\n * This file does not replace v5.5; it adds the Renaud partner events:\n *   Event 1  renaud-card-view   /_events/renaud-card-view/<surface>/<host slug>\n *   Event 2  renaud-card-click  /_events/renaud-card-click/<surface>/<host slug>\n *   Event 3  renaud-call        /_events/renaud-call/<surface>/<page slug>\n *   Supp.    renaud-website     /_events/renaud-website/ytp-profile/<page slug>\n * Surface values: ytp-card-category, ytp-card-listing, ytp-hub, ytp-profile.\n * The generator should set data-surface on the card (authoritative).\n * The inference below is a fallback only. No personal data is sent.\n * Honest limits: a card view means the card entered the viewport at\n * 50 percent visibility once; it does not prove anyone read it.\n * A call event means the tel link was tapped, not that a call connected.\n */\n(function () {\n  var PROFILE_SLUG = \"natural-skincare/renaud-naturals-loveland\";\n\n  function fire(path) {\n    try {\n      if (!window.goatcounter || !window.goatcounter.count) return;\n      window.goatcounter.count({ path: path, event: true, title: path });\n    } catch (e) {}\n  }\n\n  function pageSlug() {\n    return window.location.pathname.replace(/^\\/+|\\/+$/g, \"\");\n  }\n\n  function inferSurface(slug) {\n    /* Town hub or state page: /colorado/westminster/ or /colorado/ */\n    if (/^[a-z-]+\\/[a-z-]+$/.test(slug) && slug.indexOf(\"/\") === slug.lastIndexOf(\"/\")) {\n      var first = slug.split(\"/\")[0];\n      /* Single listing pages also have two segments, so hubs are matched\n       * by the state segment list used by the generator. When in doubt,\n       * the generator supplied data-surface wins and this never runs. */\n      var states = [\"colorado\", \"arizona\", \"california\", \"texas\", \"florida\", \"nevada\", \"utah\", \"wyoming\", \"montana\", \"idaho\", \"oregon\", \"washington\", \"new-mexico\", \"oklahoma\", \"kansas\", \"nebraska\", \"south-dakota\", \"north-dakota\", \"minnesota\", \"iowa\", \"missouri\", \"arkansas\", \"wisconsin\", \"illinois\", \"michigan\", \"indiana\", \"ohio\", \"kentucky\", \"tennessee\", \"louisiana\", \"mississippi\", \"alabama\", \"georgia\", \"alaska\", \"hawaii\", \"puerto-rico\"];\n      if (states.indexOf(first) !== -1) return \"ytp-hub\";\n      return \"ytp-card-listing\";\n    }\n    /* Category in town: /med-spas/colorado/westminster/ (3 segments) */\n    if (slug.split(\"/\").length === 3) return \"ytp-card-category\";\n    return \"ytp-card-listing\";\n  }\n\n  function firstTouchSrc(value) {\n    try {\n      var k = \"ytp_renaud_src\";\n      if (!window.sessionStorage.getItem(k)) window.sessionStorage.setItem(k, value);\n      return window.sessionStorage.getItem(k);\n    } catch (e) {\n      return value;\n    }\n  }\n\n  function arrivingSrc() {\n    try {\n      var p = new URLSearchParams(window.location.search);\n      return p.get(\"src\") || null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  function init() {\n    var slug = pageSlug();\n    if (!slug) return;\n\n    /* Events 1, 2, and the card leg of Event 3: the partner card. */\n    var card = document.querySelector('article.partnercard[data-profile=\"renaud-naturals\"]');\n    if (card) {\n      var surface = card.getAttribute(\"data-surface\") || inferSurface(slug);\n\n      if (\"IntersectionObserver\" in window) {\n        var seen = false;\n        var io = new IntersectionObserver(function (entries) {\n          for (var i = 0; i < entries.length; i++) {\n            if (entries[i].isIntersecting && !seen) {\n              seen = true;\n              fire(\"/_events/renaud-card-view/\" + surface + \"/\" + slug);\n              io.disconnect();\n            }\n          }\n        }, { threshold: 0.5 });\n        io.observe(card);\n      }\n\n      card.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (h.indexOf(\"tel:\") === 0) {\n          fire(\"/_events/renaud-call/\" + surface + \"/\" + slug);\n          return;\n        }\n        if (h.indexOf(\"/natural-skincare/renaud-naturals-loveland/\") === 0) {\n          firstTouchSrc(surface);\n          fire(\"/_events/renaud-card-click/\" + surface + \"/\" + slug);\n        }\n      });\n    }\n\n    /* Profile page bindings: Event 3 profile leg and S2 website outbound. */\n    if (slug === PROFILE_SLUG) {\n      var src = arrivingSrc();\n      if (src) firstTouchSrc(src);\n      document.addEventListener(\"click\", function (ev) {\n        var a = ev.target && ev.target.closest ? ev.target.closest(\"a\") : null;\n        if (!a) return;\n        var h = a.getAttribute(\"href\") || \"\";\n        if (a.hasAttribute(\"data-renaud-call\") || h.indexOf(\"tel:+19706671433\") === 0) {\n          fire(\"/_events/renaud-call/ytp-profile/\" + slug);\n          return;\n        }\n        if (a.hasAttribute(\"data-renaud-website\") || h.indexOf(\"https://renaudnaturals.com\") === 0) {\n          fire(\"/_events/renaud-website/ytp-profile/\" + slug);\n        }\n      });\n    }\n  }\n\n  if (document.readyState === \"loading\") {\n    document.addEventListener(\"DOMContentLoaded\", init);\n  } else {\n    init();\n  }\n})();\n\n</script>";
const HEAD_REFERENCE = "<title>Cuevas Brothers Plumbers in Westminster, CO</title><meta name=\"description\" content=\"Cuevas Brothers Plumbers is a plumber in Westminster, Colorado. It has a 4.9-star Google rating from 267 reviews. Call (970) 367-1649 or visit 5040 W 92nd.\"><link rel=\"canonical\" href=\"https://yourtownpros.com/plumbers/cuevas-brothers-plumbers-westminster/\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"icon\" href=\"/favicon.ico\" sizes=\"32x32\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:site_name\" content=\"YourTownPros\"><meta property=\"og:title\" content=\"Cuevas Brothers Plumbers in Westminster, CO\"><meta property=\"og:description\" content=\"Cuevas Brothers Plumbers is a plumber in Westminster, Colorado. It has a 4.9-star Google rating from 267 reviews. Call (970) 367-1649 or visit 5040 W 92nd.\"><meta property=\"og:url\" content=\"https://yourtownpros.com/plumbers/cuevas-brothers-plumbers-westminster/\"><meta property=\"og:image\" content=\"https://images.unsplash.com/photo-1607472586893-edb57bdc0e39?auto=format&fit=crop&w=1200&h=630&q=70\"><meta name=\"twitter:card\" content=\"summary_large_image\"><link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css\" integrity=\"sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=\" crossorigin=\"\">";

// YourTownPros listing renderer: one template, one D1 row, byte-close to the
// static page for the same business. Pure functions over a D1-shaped db
// interface (prepare(sql).bind(...).first() / .all()), so the same code runs
// in the Worker (env.DB) and locally (local-db.mjs over node:sqlite).
//
// Render read budget (brief section 3): redirect lookup 1, listing 1, trade 1,
// state 1, similar up to 5, partner card up to 1. About 10 rows, under the 30
// row cap. No query in this file scans: every lookup is a PK or index hit,
// and radius search never happens at render time (similar_pros is precomputed
// by the loader using the cell index design in schema.sql).
//
// Refresh 2026-11-14 (template refresh to the current shell): the Ship 2
// About block is generated, not harvested, so renderListing also reads the
// listing's state towns (town centers for the service-area line; indexed by
// state) and the distinct town slugs carrying the listing's trade in that
// state (the nearby-links line). Those two reads return tens of rows on the
// largest states; every other read stays a PK or index hit as before.


// The static generator serialises JSON the Python way: ", " between items and
// ": " after keys. Match it exactly or every JSON block diffs.
function pyJson(v) {
  if (v === null || v === undefined) return "null";
  if (typeof v === "number" || typeof v === "boolean") return JSON.stringify(v);
  if (typeof v === "string") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(pyJson).join(", ") + "]";
  return "{" + Object.entries(v).map(([k, x]) => `${JSON.stringify(k)}: ${pyJson(x)}`).join(", ") + "}";
}

// Python html.escape(quote=True) and urllib.parse.quote(safe="") semantics,
// which is what the static generator uses for names in text, attributes and
// claim links (apostrophes become &#x27; in HTML and %27 in URLs).
const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#x27;");
const escAttr = esc;
const enc = (s) => encodeURIComponent(String(s ?? ""))
  .replace(/'/g, "%27").replace(/\(/g, "%28").replace(/\)/g, "%29").replace(/\*/g, "%2A").replace(/!/g, "%21");
const fmtInt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ","); // Python f"{n:,}"
const unesc = (s) => String(s ?? "").replace(/&#x27;|&#39;/g, "'").replace(/&quot;/g, '"')
  .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
const fmtRating = (r) => Number(r).toFixed(1); // hero stars always print one decimal
const fmtRatingCard = (r) => String(Number(r)); // rail cards print 5, not 5.0
// Five-glyph star display rounded to the nearest half: 4.2 prints four full
// and one empty, 4.5 four full and one half, 4.8 five full.
const stars = (r) => {
  const halves = Math.round(r * 2);
  const full = Math.floor(halves / 2), half = halves % 2;
  return "★".repeat(full) + (half ? "<span class=\"starhalf\">☆<span class=\"starhalf-f\">★</span></span>" : "") + "☆".repeat(5 - full - half);
};

// ---- Ship 2 content rules, ported from the static build's transform
// (transform_content.py) so the Worker prints the same About block and the
// same JSON-LD members the static generator emits. Each function mirrors
// its Python original line for line, including its failure modes: a week
// that does not parse in full yields no hours sentence and no
// openingHoursSpecification at all.
const DAY_FULL = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const DAY_ABBR = { mon: 0, monday: 0, tue: 1, tues: 1, tuesday: 1, wed: 2, wednesday: 2,
  thu: 3, thur: 3, thurs: 3, thursday: 3, fri: 4, friday: 4, sat: 5, saturday: 5, sun: 6, sunday: 6 };

function parseHours(items) {
  const byDay = {};
  for (const it of items) {
    const m = /^\s*([A-Za-z]+)\s*[:,]\s*(.+?)\s*$/.exec(it);
    if (!m) return null;
    const d = DAY_ABBR[m[1].toLowerCase().replace(/\.+$/, "")];
    if (d === undefined) return null;
    byDay[d] = m[2];
  }
  if (Object.keys(byDay).length !== 7) return null;
  return [0, 1, 2, 3, 4, 5, 6].map((i) => byDay[i]);
}

function hoursSummary(week) {
  if (!week) return null;
  if (week.every((x) => x.toLowerCase().startsWith("open 24")))
    return "Open 24 hours, seven days a week.";
  const groups = [];
  let i = 0;
  while (i < 7) {
    let j = i;
    while (j + 1 < 7 && week[j + 1] === week[i]) j++;
    groups.push([i, j, week[i]]);
    i = j + 1;
  }
  const parts = [];
  for (const [a, b, span] of groups) {
    const day = a === b ? DAY_FULL[a] : `${DAY_FULL[a]} to ${DAY_FULL[b]}`;
    if (span.toLowerCase().startsWith("closed")) parts.push(`closed ${day}`);
    else if (span.toLowerCase().startsWith("open 24")) parts.push(`open 24 hours ${day}`);
    else {
      const spanN = span.replace(/\s*[–-]\s*/g, " to ").replace(/\s+/g, " ").trim();
      parts.push(`open ${day}, ${spanN}`);
    }
  }
  if (!parts.length) return null;
  const joined = parts.join("; ");
  return joined.charAt(0).toUpperCase() + joined.slice(1) + ".";
}

function to24(t) {
  const m = /^\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)\s*$/i.exec(t);
  if (!m) return null;
  let h = parseInt(m[1], 10) % 12;
  if (m[3].toUpperCase() === "PM") h += 12;
  return String(h).padStart(2, "0") + ":" + String(parseInt(m[2] || "0", 10)).padStart(2, "0");
}

function openingHoursSpec(week) {
  if (!week) return null;
  const out = [];
  for (let i = 0; i < 7; i++) {
    const span = week[i];
    if (span.toLowerCase().startsWith("closed")) continue;
    if (span.toLowerCase().startsWith("open 24")) {
      out.push({ "@type": "OpeningHoursSpecification", dayOfWeek: DAY_FULL[i], opens: "00:00", closes: "23:59" });
      continue;
    }
    const m = /^(.+?)\s*(?:–|-|to)\s*(.+)$/.exec(span);
    if (!m) return null;
    const o = to24(m[1]), c = to24(m[2]);
    if (o === null || c === null) return null;
    out.push({ "@type": "OpeningHoursSpecification", dayOfWeek: DAY_FULL[i], opens: o, closes: c });
  }
  return out.length ? out : null;
}

// Town-center distance exactly as the static build computes it (earth
// radius 3959 mi); used only for ordering and the rounded miles printed
// in the nearby-links line.
function havMi(a, b) {
  const la1 = a[0] * Math.PI / 180, lo1 = a[1] * Math.PI / 180;
  const la2 = b[0] * Math.PI / 180, lo2 = b[1] * Math.PI / 180;
  const h = Math.sin((la2 - la1) / 2) ** 2 + Math.cos(la1) * Math.cos(la2) * Math.sin((lo2 - lo1) / 2) ** 2;
  return 2 * 3959 * Math.asin(Math.sqrt(h));
}

function nearestTowns(l, towns, k, catSet) {
  const c0 = towns.find((x) => x.city === l.city);
  if (!c0 || c0.lat == null || c0.lng == null) return [];
  const out = [];
  for (const c of towns) {
    if (c.city === l.city) continue;
    out.push([havMi([c0.lat, c0.lng], [c.lat, c.lng]), c.city, c]);
  }
  out.sort((x, y) => (x[0] - y[0]) ||
    (x[1].toLowerCase() < y[1].toLowerCase() ? -1 : x[1].toLowerCase() > y[1].toLowerCase() ? 1 : 0));
  // Item 54 (v5.21): the Nearby radius cap. Only towns inside a
  // 25-mile radius are ever named as nearby, in the service-area
  // line or the nearby-links line; a sparse state no longer
  // presents a town 100+ miles away as a neighbour.
  const capped = out.filter(([d]) => d <= 25);
  const res = catSet ? capped.filter(([, , c]) => catSet.has(c.city_slug)) : capped;
  return res.slice(0, k);
}

function joinAnd(xs) {
  return xs.length <= 2 ? xs.join(" and ") : xs.slice(0, -1).join(", ") + " and " + xs[xs.length - 1];
}

function serviceAreaLine(l, towns) {
  const near = nearestTowns(l, towns, 3, null);
  if (!near.length) return `${esc(l.name)} serves the ${esc(l.city)} area.`;
  const names = near.map(([, nm]) => nm);
  const lst = names.length === 1 ? names[0] : joinAnd(names);
  return `${esc(l.name)} serves the ${esc(l.city)} area, including ${esc(lst)}.`;
}

function nearbyLinksLine(l, t, towns, catSet) {
  const near = nearestTowns(l, towns, 3, catSet);
  if (near.length < 2) return "";
  const bits = near.map(([dist, nm, c]) =>
    `<a href="/${l.trade_slug}/${c.state_slug}/${c.city_slug}/">${esc(nm)}</a> (${Math.round(dist)} mi)`);
  return `<p class="listed">More ${esc(t.label.toLowerCase())} nearby: ` + bits.join(" · ") + "</p>";
}

// The amen57 chips, classified the way the static build classifies them:
// the eight ownership/language attributes below by their printed phrase,
// a "Since YYYY" chip as the year, everything else as listed services.
// amen_html is the harvested chip block, so the classification runs on
// the same spans the static page prints, in page order.
const ATTR_PHRASE = { "Family-owned": "family-owned", "Locally owned": "locally owned",
  "Woman-owned": "woman-owned", "Veteran-owned": "veteran-owned",
  "Spanish-speaking": "Spanish-speaking", "Independently owned": "independently owned",
  "Latino-owned": "Latino-owned", "Women-only": "women-only" };

function amenParts(l) {
  const out = { attrs: [], services: [], since: null };
  if (!l.amen_html) return out;
  for (const m of l.amen_html.matchAll(/<span>(.*?)<\/span>/g)) {
    const sp = unesc(m[1]);
    if (Object.prototype.hasOwnProperty.call(ATTR_PHRASE, sp)) out.attrs.push(sp);
    else if (/^Since \d{4}$/.test(sp)) out.since = sp.split(" ")[1];
    else out.services.push(sp);
  }
  return out;
}

function factsParagraph(l, t, st, ap) {
  const parts = [`${esc(l.name)} is a ${esc(t.phrase)} business in ${esc(l.city)}, ${esc(st.name)}.`];
  if (l.rating != null && l.review_count != null)
    parts.push(`It holds a ${esc(l.rating_text || fmtRatingCard(l.rating))}-star ` +
      `${esc(l.rating_source || "Google")} rating from ${fmtInt(l.review_count)} reviews.`);
  const phr = ap.attrs.map((a) => ATTR_PHRASE[a]);
  if (phr.length && ap.since) {
    const joined = joinAnd(phr);
    parts.push(`${esc(joined.charAt(0).toUpperCase() + joined.slice(1))}, in business since ${esc(ap.since)}.`);
  } else if (phr.length) {
    parts.push(`${esc(l.name)} is ${esc(joinAnd(phr))}.`);
  } else if (ap.since) {
    parts.push(`In business since ${esc(ap.since)}.`);
  }
  const week = l.hours_json ? parseHours(JSON.parse(l.hours_json)) : null;
  const summ = week ? hoursSummary(week) : null;
  if (summ) parts.push(esc(summ));
  if (ap.services.length) {
    const svcs = ap.services.slice(0, 4);
    const lst = svcs.length === 1 ? svcs[0] : joinAnd(svcs);
    parts.push(`Listed work includes ${esc(lst)}.`);
  }
  let contact = `Call ${esc(l.phone)}`;
  if (l.address) contact += ` or visit ${esc(l.address)}`;
  if (l.website) contact += "; the business also has its own website, linked on this page";
  parts.push(contact + ".");
  return parts.join(" ");
}

// Street address as the meta description prints it: unit dropped, trailing
// street-type word dropped ('5040 W 92nd Ave #8600' becomes '5040 W 92nd').
const STREET_SUFFIX = new Set(["Ave", "Avenue", "St", "Street", "Blvd", "Boulevard", "Dr", "Drive",
  "Rd", "Road", "Ln", "Lane", "Ct", "Court", "Way", "Pl", "Place", "Cir", "Circle", "Hwy", "Highway",
  "Pkwy", "Parkway", "Trl", "Trail"]);
function descAddress(address) {
  if (!address) return null;
  const noUnit = address.split("#")[0].trim().replace(/,$/, "");
  const words = noUnit.split(/\s+/);
  if (words.length > 3 && STREET_SUFFIX.has(words[words.length - 1])) words.pop();
  return words.join(" ");
}

function head(l, t, st) {
  // Title, description and og:title are listing data (their wording depends
  // on rating, address and phone in ways the data files do not fully
  // determine), so the loader harvests them verbatim from the static page.
  const base = `${esc(l.name)} in ${esc(l.city)}, ${l.state}`;
  const title = l.page_title || (l.rating != null ? base : `${base}: Phone Number | YourTownPros`);
  const ogTitle = l.og_title || (l.rating != null ? base : `${base}: Phone Number`);
  let desc = l.meta_desc;
  if (!desc) {
    desc = `${l.name} is a ${t.singular} in ${l.city}, ${st.name}.`;
    if (l.rating != null) {
      desc += ` It has a ${fmtRating(l.rating)}-star Google rating from ${l.review_count} reviews.`;
      desc += ` Call ${l.phone} or visit ${descAddress(l.address)}.`;
    } else if (l.phone) {
      desc += ` Call ${l.phone}. Owners can claim this free listing.`;
    }
  }
  const url = `https://yourtownpros.com/${l.path}/`;
  // Batch publish gate (2026-11-14): a listing whose indexable flag is 0
  // serves with a noindex robots meta; 1 or absent (every pre-gate row,
  // and any database the schema delta has not reached) prints nothing
  // extra, byte-identical to the pre-gate head.
  const robots = l.indexable === 0 ? `<meta name="robots" content="noindex">` : ``;
  return `<title>${title}</title><meta name="description" content="${desc}">` + robots +
    `<link rel="canonical" href="${url}">` +
    `<link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="icon" href="/favicon.ico" sizes="32x32">` +
    `<link rel="apple-touch-icon" href="/apple-touch-icon.png">` +
    `<meta property="og:type" content="website"><meta property="og:site_name" content="YourTownPros">` +
    `<meta property="og:title" content="${ogTitle}"><meta property="og:description" content="${desc}">` +
    `<meta property="og:url" content="${url}"><meta property="og:image" content="${l.image_url || t.og_image}">` +
    `<meta name="twitter:card" content="summary_large_image">` +
    `<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="">`;
}

function crumb(l, t, st) {
  const head = `<main class="wrap" id="main"><nav class="crumb" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/${l.trade_slug}/">${esc(t.label)}</a> / ` +
    `<a href="/${l.trade_slug}/${l.state_slug}/">${esc(st.name)}</a> / `;
  if (!l.crumb_linked) return head + `${esc(l.city)}</nav>`;
  return head +
    `<a href="/${l.trade_slug}/${l.state_slug}/${l.city_slug}/" title="${escAttr(t.label)} in ${escAttr(st.name)}">${esc(t.label)} in ${esc(l.city)}</a></nav>`;
}

function hero(l, t) {
  // Item 50: a listing with no photo of its own renders a compact
  // trade header, never a stock band borrowed from the trade or a
  // blank rectangle.
  if (!l.image_url) {
    return `<div class="bizhero57 noimg"><span class="heroicon"><svg viewBox="0 0 512 512" aria-hidden="true" focusable="false"><path d="M256 36c-82 0-148 66-148 148 0 104 148 292 148 292s148-188 148-292c0-82-66-148-148-148z" fill="#0e7a5f"/><circle cx="256" cy="184" r="84" fill="#ffffff"/></svg></span>` +
      `<span class="herotrade">${esc(t.label)} in ${esc(l.city)}, ${l.state}</span></div>`;
  }
  const base = String(l.image_url || t.og_image).split("?")[0];
  const img = (w) => `${base}?auto=format&amp;fit=crop&amp;w=${w}&amp;q=60`;
  return `<div class="bizhero57"><img class="photoband-img" src="${img(1200)}" ` +
    `srcset="${img(480)} 480w, ${img(828)} 828w, ${img(1200)} 1200w" sizes="100vw" width="1200" height="180" ` +
    `fetchpriority="high" alt="Stock photo: ${escAttr(t.phrase)} in ${escAttr(l.city)}, ${l.state}" onerror="this.parentNode.classList.add('imgfail62');this.remove()"></div>`;
}

function h1block(l, t) {
  // Refresh 2026-11-14: the stars line names the row's own rating source
  // (the v5.17 label fix); the label comes from the data, not a constant.
  const src = `${esc(l.rating_source || "Google")} rating`;
  let s = `<h1>${esc(l.name)}</h1><span class="pill">${esc(t.label)}</span><span class="pill">${esc(l.city)}, ${l.state}</span>`;
  if (l.rating != null && l.review_count != null) s += `<p class="stars">${stars(l.rating)} ${l.rating_text || fmtRatingCard(l.rating)} · ${l.review_count} reviews <span class="gsrc">${src}</span></p>`;
  else if (l.rating != null) s += `<p class="stars">${stars(l.rating)} ${l.rating_text || fmtRatingCard(l.rating)} <span class="gsrc">${src}</span></p>`;
  else if (l.review_count != null) s += `<p class="stars">${l.review_count} reviews <span class="gsrc">${src}</span></p>`;
  // Item 52: badges render only from fields this listing's own
  // record holds (attrs_json; a since year when the row carries
  // one). Claimed renders at runtime through the claim script,
  // never baked here.
  let badges = "";
  let attrs = [];
  try { attrs = JSON.parse(l.attrs_json || "[]"); } catch (e) { attrs = []; }
  if (Array.isArray(attrs) && attrs.includes("Family-owned")) badges += `<span class="badg52">Family-Owned</span>`;
  if (l.since != null && /^\d{4}$/.test(String(l.since))) badges = `<span class="badg52">Est. ${esc(String(l.since))}</span>` + badges;
  if (badges) s += `<div class="badges52">${badges}</div>`;
  return s;
}

function about(l, t, st, towns, catSet) {
  // Ship 2 form: a generated facts paragraph (or the owner copy for
  // enriched listings), then the service-area line and, when at least two
  // nearby towns carry this trade, the nearby-links line. The old
  // "listed in the directory" trailer was removed sitewide by Ship 2.
  const tail = `<p>${serviceAreaLine(l, towns)}</p>` + nearbyLinksLine(l, t, towns, catSet);
  if (l.from_business) {
    return `<h2>From this business</h2><p>${l.from_business}</p>` + tail;
  }
  return `<h2>About ${esc(l.name)}</h2><p>${factsParagraph(l, t, st, amenParts(l))}</p>` + tail;
}

function amen(l) {
  return l.amen_html ? `<h2>Amenities and services</h2><div class="amen57">${l.amen_html}</div>` : "";
}

// biz-data addresses come in many shapes: bare street, street plus
// ', City, ST', street plus ZIP only, street with the city appended
// without a comma, full state names, ZIP+4. fullAddress and streetParts
// below follow the static generator's own rules for the two consumers
// (the map directions link and the JSON-LD streetAddress/postalCode).
// The contact card's link is a third rule: it appends ', City, ST'
// unconditionally (it visibly duplicates on addresses that already carry
// it; that is what the static pages print).
function fullAddress(l) {
  // The generator's directions rule (s15 _listing_map), both map modes:
  // the address goes in as-is when it already contains ", {ST}",
  // otherwise ", {City}, {ST}" is appended (even when that duplicates a
  // trailing city name the address carries without the state).
  // Refresh 2026-11-14: this replaces the older suffix-matching rule,
  // which diverged on ZIP+4 and full-state-name addresses.
  if (!l.address) return null;
  return l.address.includes(`, ${l.state}`) ? l.address : `${l.address}, ${l.city}, ${l.state}`;
}
// The map block's pin label address: the street line from streetParts
// plus ", {City}, {ST}", or just "{City}, {ST}" when there is no street.
function lmapAddress(l) {
  const sp = streetParts(l);
  return sp.street ? `${sp.street}, ${l.city}, ${l.state}` : `${l.city}, ${l.state}`;
}
const escRe = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
function streetParts(l) {
  // Ported from the static generator (s09 street_parts): the streetAddress
  // never repeats city or state. The ZIP (first five digits) comes off the
  // end first, then the state code, then ", City", then a trailing
  // " City"; an address that reduces to the bare city has no street.
  if (!l.address) return { street: null, zip: null };
  let s = l.address.trim();
  let zip = null;
  const zm = /(\d{5})(?:-\d{4})?\s*$/.exec(s);
  if (zm) { zip = zm[1]; s = s.slice(0, zm.index).trim(); }
  s = s.replace(new RegExp(",?\\s*" + escRe(l.state) + "\\s*$"), "").trim();
  s = s.replace(new RegExp(",\\s*" + escRe(l.city) + "\\s*$", "i"), "").trim();
  if (l.city && s.toLowerCase().endsWith(" " + l.city.toLowerCase()))
    s = s.slice(0, s.length - l.city.length - 1).trim();
  s = s.replace(/,+$/, "").trim();
  if (s.toLowerCase() === l.city.toLowerCase()) s = "";
  return { street: s || null, zip };
}
function directionsUrl(l) {
  const dest = l.address ? fullAddress(l) : `${l.city}, ${l.state}`;
  return `https://www.google.com/maps/dir/?api=1&destination=${enc(dest)}`;
}
function contactDirectionsUrl(l) {
  return `https://www.google.com/maps/dir/?api=1&destination=${enc(`${l.address}, ${l.city}, ${l.state}`)}`;
}

function lochrs(l) {
  let left;
  if (l.pin_source === "pin") {
    const data = { mode: "pin", lat: l.lat, lng: l.lng, name: l.name, addr: lmapAddress(l) };
    left = `<div><div class="lmapwrap"><div id="ytp-lmap" class="lmap"></div></div>` +
      `<p><a href="${directionsUrl(l)}">Get directions</a></p>` +
      `<script type="application/json" id="ytp-lmap-data">${pyJson(data)}</script></div>`;
  } else {
    const data = { mode: "city", lat: l.lat, lng: l.lng, city: `${l.city}, ${l.state}` };
    left = `<div><div class="lmapwrap"><div id="ytp-lmap" class="lmap"></div>` +
      `<p class="mapcap">Business pins appear here as addresses are verified.</p></div>` +
      (l.address ? `<p><a href="${directionsUrl(l)}">Get directions</a></p>` : "") +
      `<script type="application/json" id="ytp-lmap-data">${pyJson(data)}</script></div>`;
  }
  const sp62 = streetParts(l);
  const addr62 = sp62.street ? `${esc(sp62.street)}, ${esc(l.city)}, ${l.state}${sp62.zip ? " " + sp62.zip : ""}` : `${esc(l.city)}, ${l.state}`;
  let right = `<div><p>${addr62}</p>`;
  if (l.hours_json) {
    const items = JSON.parse(l.hours_json).map((h) => `<li>${esc(h)}</li>`).join("");
    right += `<p class="opennow" id="ytp-opennow" data-tz="${l.hours_tz}" hidden></p><ul class="hourslist">${items}</ul>`;
    if (l.hours_checked) right += `<p class="listed">Hours checked ${esc(l.hours_checked)}.</p>`;
  } else {
    right += `<p class="hoursnone"><strong>Hours not listed yet</strong></p>` +
      `<p class="listed claiminvite">Is this your business? <a href="/claim/?business=${l.path}&name=${enc(l.name)}">Claim this free listing</a> to add your hours.</p>`;
  }
  right += `</div>`;
  return `<div class="lochrs57">${left}${right}</div>`;
}

function feat(l, t) {
  // Ship 2 E8.3: the Featured pitch collapsed to the Sponsored label only.
  return `<div class="feat"><div class="k">Sponsored · Featured spot open</div></div>`;
}

// Item 49 CTA modes (same map as the static generator and the
// tree patcher): quote trades lead with a quote form carrying
// need options, appointment trades with an appointment request,
// walk-in food and retail lead with direct contact actions.
const CTA_QUOTE = new Set(["plumbers", "hvac", "electricians", "auto-repair", "auto-glass", "roofing", "handyman", "lawn-and-landscaping", "painting", "towing", "locksmiths", "tree-service", "pest-control", "movers", "flooring", "concrete-contractors", "kitchen-remodelers", "bathroom-remodelers", "general-contractors", "pool-builders", "architects", "interior-designers"]);
const CTA_APPT = new Set(["hair-salons", "barbers", "nails", "massage", "spas", "med-spas", "natural-skincare", "pet-grooming", "pet-boarding", "tattoo", "fitness", "dance-studios", "veterinary", "chiropractors", "dentists", "optometrists", "photographers"]);
const CTA_WALKIN = new Set(["bakeries-and-cafes", "florists", "bookstores", "jewelry", "cleaners", "pawn-shops", "bars"]);
const NEED_SETS = {
  "plumbers": ["Fix a leak, clog, or backup", "Install or replace a fixture or appliance", "Water heater repair or replacement", "Remodel or new construction", "Something else"],
  "hvac": ["Repair my heating or cooling system", "Install or replace a system", "Maintenance or tune-up", "Something else"],
  "auto-repair": ["Diagnose a problem", "Brakes, tires, or suspension", "Oil change or scheduled maintenance", "Engine or transmission work", "Something else"],
  "auto-glass": ["Replace a windshield", "Repair a chip or crack", "Replace a side or rear window", "Something else"],
  "electricians": ["Fix an electrical problem", "Install lighting, outlets, or a panel", "Wiring for a remodel or addition", "Something else"],
  "roofing": ["Repair a leak or damage", "Replace my roof", "New roof installation", "Inspection or estimate", "Something else"],
  "architects": ["Design a custom home", "Addition or remodel drawings", "Commercial space design", "Permit drawings", "Something else"],
  "interior-designers": ["Design a whole home", "Kitchen or bath design", "One room refresh", "Color, furniture, and finishes", "Something else"],
};
const NEED_DEFAULT = ["Repair or fix something", "Install or replace something", "New project or remodel", "Something else"];
function ctaMode(slug) {
  if (CTA_QUOTE.has(slug)) return "quote";
  if (CTA_APPT.has(slug)) return "appt";
  if (CTA_WALKIN.has(slug)) return "walkin";
  return "default";
}
function ctaLabel(mode) {
  return mode === "quote" ? "Get Free Quote" : mode === "appt" ? "Check Availability" : "Request this pro";
}
function simReqHtml(path, mode) {
  // Item 76: similar pros share the listing's trade, so their card
  // request link takes that trade's archetype label; walk-in shops
  // carry no request link on cards at all.
  if (mode === "walkin") return "";
  const lbl = mode === "quote" ? "Get Free Quote" : mode === "appt" ? "Check Availability" : "Request this pro";
  return `<div class="meta cardreq"><a href="/${path}/?src=card#match">${lbl}</a></div>`;
}
function callLabel(l, mode) {
  // Item 76: emergency trades lead with Call Now, appointment
  // trades with Call to Book; the number stays visible in both.
  if (l.trade_slug === "towing" || l.trade_slug === "locksmiths") return "Call Now ";
  if (mode === "appt") return "Call to Book ";
  return "Call ";
}
function needOptsHtml(slug) {
  if (ctaMode(slug) !== "quote") return "";
  const opts = NEED_SETS[slug] || NEED_DEFAULT;
  return `<fieldset class="needopts"><legend>What do you need?</legend>` +
    opts.map((o) => `<label><input type="radio" name="service_need" value="${escAttr(o)}"> ${esc(o)}</label>`).join("") +
    `</fieldset>\n`;
}

function matchopen(l, t, similars, held) {
  // Ship 2 E8.1: the match form is collapsed behind a details button.
  // Item 49: the heading follows the trade's CTA mode; walk-in
  // trades lead with direct contact actions and keep the form as
  // a message option inside the collapse.
  const mode = ctaMode(l.trade_slug);
  if (held) {
    // Lead hold, held-page v3 (owner, Nov 18, 2026): the request
    // goes to the town pool, never to this listing, and exactly
    // ONE competitor leads the block: the same single competitor
    // the Similar rail below carries.
    const label = mode === "quote" ? "Get Free Quote" : mode === "appt" ? "Request Appointment" : mode === "walkin" ? "Message the Business" : "Request this pro";
    const intro = `<p style="margin:0">Tell us what you need. Your request comes to YourTownPros first: we match you with an available ${esc(l.city)} ${esc(t.phrase)} pro.</p>\n`;
    const formOpen = `<form action="https://formsubmit.co/ajax/yourtownpros@gmail.com" method="POST" id="ytp-match-form" data-match-slug="" data-match-source="listing">\n` +
      `<input type="hidden" name="_subject" value="Match request: ${escAttr(t.label)}, ${escAttr(l.city)}"><input type="hidden" name="_template" value="table"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_cc" value="leads@muse.ai"><div class="hpf" aria-hidden="true"><label>Company website<input type="text" name="company_website" tabindex="-1" autocomplete="off"></label></div>`;
    const strip = (similars || []).slice(0, 1).map((x) => `<div class="card"><h3><a href="/${x.path}/">${esc(x.name)}</a></h3>${simReqHtml(x.path, mode)}</div>`).join("");
    const stripHtml = strip ? `<div class="similar"><h2>${esc(t.label)} pros in ${esc(l.city)}</h2><div class="grid">${strip}</div></div>` : "";
    return stripHtml + `<div class="match" id="match"><details class="ytp-collapse"><summary class="ytp-collapse-btn">${label}</summary><h2>${label}</h2>` + intro + formOpen;
  }
  const intro = `<p style="margin:0">Tell us what you need. Your request comes to YourTownPros first: we contact ${esc(l.name)} about it, and if they cannot take the job, we match you with another ${esc(l.city)} ${esc(t.phrase)} pro instead.</p>\n`;
  const formOpen = `<form action="https://formsubmit.co/ajax/yourtownpros@gmail.com" method="POST" id="ytp-match-form" data-match-slug="${l.path}" data-match-source="listing">\n` +
    `<input type="hidden" name="_subject" value="Match request: ${escAttr(t.label)}, ${escAttr(l.city)} (via ${escAttr(l.name)} listing)"><input type="hidden" name="_template" value="table"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_cc" value="leads@muse.ai"><div class="hpf" aria-hidden="true"><label>Company website<input type="text" name="company_website" tabindex="-1" autocomplete="off"></label></div>`;
  if (mode === "walkin") {
    let acts = "";
    if (l.phone) acts += `<a href="tel:${l.phone_digits}">Call ${esc(l.phone)}</a>`;
    if (l.address) acts += `<a href="${contactDirectionsUrl(l)}" target="_blank" rel="noopener">Get directions</a>`;
    if (l.show_website_link && l.website) acts += `<a href="${escAttr(l.website)}" target="_blank" rel="ugc nofollow noopener noreferrer">Visit their website</a>`;
    return `<div class="match" id="match"><h2>Contact this business</h2><div class="walkacts">${acts}</div>` +
      `<details class="ytp-collapse"><summary class="ytp-collapse-btn">Message the Business</summary><h2>Message the Business</h2>` + intro + formOpen;
  }
  const label = mode === "quote" ? "Get Free Quote" : mode === "appt" ? "Request Appointment" : "Request this pro";
  return `<div class="match" id="match"><details class="ytp-collapse"><summary class="ytp-collapse-btn">${label}</summary><h2>${label}</h2>` + intro + formOpen;
}

function contact(l, held) {
  let s = `<div class="bizcard57"><h2>Contact</h2>`;
  if (l.phone && !held) s += `<p><a class="tel" href="tel:${l.phone_digits}">${callLabel(l, ctaMode(l.trade_slug))}${esc(l.phone)}</a></p>`;
  if (l.show_website_link && l.website)
    s += `<a class="act57" href="${escAttr(l.website)}" target="_blank" rel="ugc nofollow noopener noreferrer">Visit their website</a>`;
  if (l.address)
    s += `<a class="act57" href="${contactDirectionsUrl(l)}" target="_blank" rel="noopener">Get directions</a>`;
  const mode = ctaMode(l.trade_slug);
  const label = mode === "walkin" ? "Message the Business" : ctaLabel(mode);
  s += `<a class="act57" href="#match">${label}</a></div>`;
  return s;
}

function claimstrip(l, held) {
  if (held) {
    // Held-page v3 rule 1: the official number stays on the page,
    // de-emphasized under the match form, never as a Call button.
    if (!l.phone) return "";
    return `<p class="fine" style="margin:14px 0 0">Want to try calling ${esc(l.name)} yourself? Their official number is <a href="tel:${l.phone_digits}">${esc(l.phone)}</a>.</p>`;
  }
  return `<div class="claimstrip">Is this your business? <a href="/claim/?business=${l.path}&name=${enc(l.name)}">Claim this free listing</a> to keep your hours, services and photos current.</div>`;
}

function jsonld(l, t) {
  const o = { "@context": "https://schema.org", "@type": t.schema_type,
    "@id": `https://yourtownpros.com/${l.path}/#business`, name: l.name,
    url: `https://yourtownpros.com/${l.path}/` };
  if (l.phone_digits) o.telephone = l.phone_digits;
  const addr = { "@type": "PostalAddress", addressLocality: l.city, addressRegion: l.state, addressCountry: "US" };
  const sp = streetParts(l);
  if (sp.street) addr.streetAddress = sp.street;
  if (sp.zip) addr.postalCode = sp.zip;
  o.address = addr;
  if (l.website && l.show_website_link) o.sameAs = [l.website];
  // Refresh 2026-11-14: the static build appends geo (only where the page
  // carries a verified pin, which is exactly pin_source "pin") and then
  // openingHoursSpecification (only from recorded hours that parse as a
  // full week), in this order, after the generator's own members.
  if (l.pin_source === "pin" && l.lat != null && l.lng != null)
    o.geo = { "@type": "GeoCoordinates", latitude: l.lat, longitude: l.lng };
  if (l.hours_json) {
    const spec = openingHoursSpec(parseHours(JSON.parse(l.hours_json)));
    if (spec) o.openingHoursSpecification = spec;
  }
  return `<script type="application/ld+json">${pyJson(o)}</script>`;
}

function breadcrumbSimilar(l, t, st, similars, partner, hubExists) {
  // Position 4 (generator T3.2): with a category page it links that page;
  // without one it takes the bare city name and links the city hub, or
  // the state hub where the town has no hub page either (hubExists).
  const items = [
    { "@type": "ListItem", position: 1, name: "Home", item: "https://yourtownpros.com/" },
    { "@type": "ListItem", position: 2, name: t.label, item: `https://yourtownpros.com/${l.trade_slug}/` },
    { "@type": "ListItem", position: 3, name: st.name, item: `https://yourtownpros.com/${l.trade_slug}/${l.state_slug}/` },
    l.crumb_linked
      ? { "@type": "ListItem", position: 4, name: `${t.label} in ${l.city}`, item: `https://yourtownpros.com/${l.trade_slug}/${l.state_slug}/${l.city_slug}/` }
      : { "@type": "ListItem", position: 4, name: l.city, item: hubExists ? `https://yourtownpros.com/${l.state_slug}/${l.city_slug}/` : `https://yourtownpros.com/${l.state_slug}/` },
    { "@type": "ListItem", position: 5, name: l.name, item: `https://yourtownpros.com/${l.path}/` },
  ];
  const bc = { "@context": "https://schema.org", "@type": "BreadcrumbList", itemListElement: items };
  let s = `<script type="application/ld+json">${pyJson(bc)}</script>`;
  if (similars.length === 0) {
    // An empty rail omits the whole similar block on the static pages.
    if (partner) s += partnerCard(partner);
    return s;
  }
  const cards = similars.map((x) => {
    let c = `<div class="card"><h3><a href="/${x.path}/">${esc(x.name)}</a></h3>`;
    const xsrc = `${esc(x.rating_source || "Google")} rating`;
    if (x.rating != null && x.review_count != null) c += `<div class="stars">${stars(x.rating)} ${x.rating_text || fmtRatingCard(x.rating)} · ${x.review_count} reviews <span class="gsrc">${xsrc}</span></div>`;
    else if (x.rating != null) c += `<div class="stars">${stars(x.rating)} ${x.rating_text || fmtRatingCard(x.rating)} <span class="gsrc">${xsrc}</span></div>`;
    else if (x.review_count != null) c += `<div class="stars">${x.review_count} reviews <span class="gsrc">${xsrc}</span></div>`;
    c += `<div class="listed">Listed in ${esc(x.city)}</div>`;
    if (x.address) c += `<div class="meta">${esc(x.address)}</div>`;
    else c += `<div class="meta">${esc(x.city)}, ${x.state}</div>`;
    if (x.phone) c += `<div class="meta">${esc(x.phone)}</div>`;
    c += simReqHtml(x.path, ctaMode(l.trade_slug)) + "</div>";
    return c;
  }).join("");
  // Rail footer second link (generator T4.6 #7): the city hub when the
  // town has one, else the category page ("Other pros in {city}"), else
  // the trade-in-state page ("Other pros in {state}").
  const link2 = hubExists
    ? `<a href="/${l.state_slug}/${l.city_slug}/">All local businesses in ${esc(l.city)}, ${l.state}</a>`
    : l.crumb_linked
      ? `<a href="/${l.trade_slug}/${l.state_slug}/${l.city_slug}/">Other pros in ${esc(l.city)}</a>`
      : `<a href="/${l.trade_slug}/${l.state_slug}/">Other pros in ${esc(st.name)}</a>`;
  s += `<div class="similar"><h2>Similar pros nearby</h2><div class="grid">${cards}</div>` +
    `<p><a href="/${l.trade_slug}/${l.state_slug}/">More ${esc(t.label)} in ${esc(st.name)}</a> · ` +
    `${link2}</p></div>`;
  if (partner) s += partnerCard(partner);
  return s;
}

function partnerCard(partner) {
  return `<article class="partnercard" data-profile="${partner.partner_id}" data-slug="${partner.profile_path}" data-surface="ytp-card-listing">` +
    `<p class="sponline">Sponsored · Featured</p><h3>${esc(partner.name)}</h3><p>${esc(partner.blurb)}</p>` +
    `<p><a href="/${partner.profile_path}/?src=ytp-card-listing">${esc(partner.link_text)}</a></p></article>`;
}

async function renderListing(db, path) {
  const l = await db.prepare("SELECT * FROM listings WHERE path = ?").bind(path).first();
  if (!l) return null;
  const t = await db.prepare("SELECT * FROM trades WHERE trade_slug = ?").bind(l.trade_slug).first();
  const st = await db.prepare("SELECT * FROM states WHERE state = ?").bind(l.state).first();
  const sim = await db.prepare(
    "SELECT x.*, s.distance_mi AS sim_dist FROM similar_pros s JOIN listings x ON x.path = s.similar_path WHERE s.path = ? ORDER BY s.rank")
    .bind(path).all();
  const pc = await db.prepare(
    "SELECT p.* FROM listing_partner_cards c JOIN partner_cards p ON p.partner_id = c.partner_id" +
    " WHERE c.path = ? AND p.trade_slug = ? AND p.active = 1 LIMIT 1").bind(path, l.trade_slug).first();
  // Refresh 2026-11-14: the Ship 2 About lines and the breadcrumb
  // state-hub fallback need the town universe of the listing's state.
  const townRes = await db.prepare(
    "SELECT city, city_slug, state_slug, lat, lng FROM towns WHERE state = ?").bind(l.state).all();
  const towns = townRes.results || [];
  const catRes = await db.prepare(
    "SELECT city_slug FROM category_towns WHERE trade_slug = ? AND state_slug = ?")
    .bind(l.trade_slug, l.state_slug).all();
  const catSet = new Set((catRes.results || []).map((r) => r.city_slug));
  const hubExists = towns.some((x) => x.city_slug === l.city_slug);

  const holdSet = await leadHold(db);
  const held = holdSet.has(l.path);
  // Item 54 (v5.21): the Nearby radius cap on the Similar pros rail.
  // Precomputed edges carry a distance_mi (town-center basis at load
  // time; when an edge has none, the town-center distance is computed
  // here from the towns table). An edge past 25 miles is never
  // presented as nearby: the Pembroke Pines audit case offered Tampa
  // at 192 mi and Jacksonville at 312 mi. Below 3 same-trade pros
  // inside the radius, the rail fills at render time (the
  // nearest-fill owed since item 5): nearest same-trade towns inside
  // the radius first, then other trades in the same town. The county
  // tier of the fallback chain needs county data the D1 towns table
  // does not carry, so it stays a static-generator tier.
  const townBySlug = new Map(towns.map((x) => [x.city_slug, x]));
  const myTown = townBySlug.get(l.city_slug);
  const townDist = (x) => {
    if (x.city_slug === l.city_slug) return 0;
    const o = townBySlug.get(x.city_slug);
    if (!myTown || !o || myTown.lat == null || o.lat == null) return null;
    return havMi([myTown.lat, myTown.lng], [o.lat, o.lng]);
  };
  let simRows = (sim.results || []).filter((x) => !holdSet.has(x.path))
    .filter((x) => {
      const d = x.sim_dist != null ? x.sim_dist : townDist(x);
      return d != null ? d <= 25 : x.city_slug === l.city_slug;
    });
  if (!held && simRows.length < 3) {
    const have = new Set(simRows.map((x) => x.path));
    const nearSlugs = towns
      .filter((x) => myTown && x.lat != null &&
        (x.city_slug === l.city_slug ||
         havMi([myTown.lat, myTown.lng], [x.lat, x.lng]) <= 25))
      .map((x) => x.city_slug);
    if (nearSlugs.length) {
      const ph = nearSlugs.map(() => "?").join(",");
      const fillRes = await db.prepare(
        `SELECT * FROM listings WHERE trade_slug = ? AND state = ? AND path != ? AND city_slug IN (${ph})`)
        .bind(l.trade_slug, l.state, path, ...nearSlugs).all();
      const fills = (fillRes.results || [])
        .filter((x) => !have.has(x.path) && !holdSet.has(x.path))
        .map((x) => [townDist(x), x])
        .filter(([d]) => d != null && d <= 25)
        .sort((a, b) => (a[0] - b[0]) ||
          ((b[1].review_count || -1) - (a[1].review_count || -1)) ||
          ((b[1].rating || -1) - (a[1].rating || -1)));
      for (const [, x] of fills) {
        if (simRows.length >= 4) break;
        simRows.push(x); have.add(x.path);
      }
    }
    if (simRows.length < 3) {
      const t2Res = await db.prepare(
        "SELECT * FROM listings WHERE state = ? AND city_slug = ? AND trade_slug != ? AND path != ? ORDER BY review_count DESC")
        .bind(l.state, l.city_slug, l.trade_slug, path).all();
      for (const x of (t2Res.results || [])) {
        if (simRows.length >= 4) break;
        if (have.has(x.path) || holdSet.has(x.path)) continue;
        simRows.push(x); have.add(x.path);
      }
    }
    simRows = simRows.slice(0, 4);
  }

  let html = TEMPLATE;
  const slots = {
    "{{HEAD}}": head(l, t, st),
    "{{CRUMB}}": crumb(l, t, st),
    "{{HERO}}": hero(l, t),
    "{{H1BLOCK}}": h1block(l, t),
    "{{ABOUT}}": about(l, t, st, towns, catSet),
    "{{AMEN}}": amen(l),
    "{{LOCHRS}}": lochrs(l),
    "{{FEAT}}": feat(l, t),
    "{{MATCHOPEN}}": matchopen(l, t, simRows, held),
    "{{NEEDOPTS}}": needOptsHtml(l.trade_slug),
    "{{SVC_LABEL}}": ctaMode(l.trade_slug) === "quote" ? "Describe the job (optional)" : "What do you need?",
    "{{SUBMIT_LABEL}}": ctaMode(l.trade_slug) === "walkin" ? "Send message" : "Send request",
    "{{PLACEHOLDER}}": escAttr(t.service_placeholder || ""),
    "{{SG_NAME}}": esc(l.name),
    "{{SG_CAT}}": esc(t.label),
    "{{SG_ADDR}}": esc(l.address || "Address not listed"),
    "{{SG_PHONE}}": esc(l.phone || "Phone not listed"),
    "{{CONTACT}}": contact(l, held),
    "{{CLAIMSTRIP}}": claimstrip(l, held),
    "{{JSONLD}}": jsonld(l, t),
    "{{BREADCRUMB_SIMILAR}}": breadcrumbSimilar(l, t, st, held ? simRows.slice(0, 1) : simRows, held ? null : pc, hubExists),
    "{{OPENNOW}}": l.hours_json ? OPENNOW_SCRIPT : "",
    "{{RENTRACK}}": pc ? RENTRACK_SCRIPT : "",
  };
  for (const [k, v] of Object.entries(slots)) html = html.split(k).join(v);
  html = html.split("{{PATH}}").join(l.path);
  html = html.split("{{TRADE_SLUG}}").join(l.trade_slug);
  html = html.split("{{CITY}}").join(l.city);
  return html;
}

async function lookupRedirect(db, path) {
  const r = await db.prepare("SELECT to_path, status FROM redirects WHERE from_path = ?").bind(path).first();
  return r || null;
}

// Cloudflare Worker entry for listing pages (gate d). NOT deployed by this
// build; deployment is an account step listed in ACCOUNT-STEPS.md.
//
// Routing contract (brief sections 1 and 2): one Worker route per trade
// matches the two-segment listing pattern /<trade>/<business-slug>-<town>/.
// The Worker re-checks the path shape itself and passes anything that is not
// a true listing straight through to the static origin, so a misfire costs
// one pass-through, never a wrong page. Every route is set FAIL OPEN in the
// dashboard, so hitting the daily request cap bypasses the Worker instead of
// erroring (brief section 3). Bot features stay OFF on the zone (brief
// section 6); nothing in this Worker challenges any user agent.
//
// Cache layer (renderer-cache-design-2026-11-14.md sections 2.2 and 2.3):
// rendered listing pages are served from the Workers Cache API and the
// Worker renders only on a cache miss. The cache key is the listing URL
// (query stripped, per the design) plus the dataset version read from the
// meta table, so a data ship soft-purges the whole rendered set by bumping
// the version: entries under the old key are never requested again. The
// version is read once per isolate lifecycle and memoised in memory,
// refreshed on a 60 second interval, so it costs one D1 row per isolate
// per interval, not one per render. An unknown slug's 404 is cached for
// 10 minutes (negative caching). Every cache operation fails open: a
// cache error or a missing Cache API falls back to rendering, and the
// static site remains the fallback behind the pass-through paths below.


const LISTING_PATH = /^\/([a-z0-9-]+)\/([a-z0-9-]+)\/?$/;

// The _headers general rule for rendered pages (the Pages _headers file does
// not apply to Worker responses, so the Worker sets the same values itself).
const PAGE_HEADERS = {
  "Content-Type": "text/html; charset=utf-8",
  "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "SAMEORIGIN",
  "Cache-Control": "public, max-age=0, must-revalidate",
};

// Rendered listing pages carry the design's cacheable Cache-Control instead
// (section 2.2): a 30 day edge TTL via s-maxage, stale-while-revalidate so a
// revalidation never blocks a visitor or a crawler, and stale-if-error so a
// D1 or Worker fault serves the last good render. max-age stays 0 so a
// browser revalidates exactly as it does against the static site today.
const LISTING_HEADERS = {
  ...PAGE_HEADERS,
  "Cache-Control":
    "public, max-age=0, s-maxage=2592000, stale-while-revalidate=86400, stale-if-error=2592000",
};

// Unknown slugs: the 404 outcome is cached for 10 minutes (section 2.2).
const NEGATIVE_CACHE_CONTROL = "public, max-age=600, s-maxage=600";

// Dataset version (section 2.3): the loader writes meta['dataset_version']
// on every data import. Payloads that predate the key read as version "0";
// their entries simply never purge until the first versioned ship lands.
const VERSION_KEY = "dataset_version";
const VERSION_FALLBACK = "0";
const VERSION_REFRESH_MS = 60_000;
let versionMemo = { value: null, at: 0 };

async function datasetVersion(db) {
  const now = Date.now();
  if (versionMemo.value !== null && now - versionMemo.at < VERSION_REFRESH_MS) {
    return versionMemo.value;
  }
  let value = versionMemo.value !== null ? versionMemo.value : VERSION_FALLBACK;
  try {
    const row = await db
      .prepare("SELECT value FROM meta WHERE key = ?")
      .bind(VERSION_KEY)
      .first();
    if (row && row.value !== null && row.value !== undefined && row.value !== "") {
      value = String(row.value);
    }
  } catch {
    // Fail open: keep the last known version (or the fallback). A version
    // read fault must never take a listing page down with it.
  }
  versionMemo = { value, at: now };
  return value;
}

// Lead hold registry (the kill switch): meta['lead_hold'] holds a
// JSON array written by dated D1 deltas. Entries are listing path
// strings (level "full" implied) or objects {path, level}; only
// "full" entries hold. A listing that claims flips to "soft" by a
// dated delta and renders normally again. A held listing keeps its
// page and its facts, but loses featured placement, drops out of
// other listings' Similar pros rails, shows exactly one competitor,
// and its match form diverts to the town pool. Read with the same
// memo pattern as the dataset version.
const LEAD_HOLD_KEY = "lead_hold";
const LEAD_HOLD_REFRESH_MS = 60_000;
let leadHoldMemo = { set: null, at: 0 };

async function leadHold(db) {
  const now = Date.now();
  if (leadHoldMemo.set !== null && now - leadHoldMemo.at < LEAD_HOLD_REFRESH_MS) {
    return leadHoldMemo.set;
  }
  let set = leadHoldMemo.set !== null ? leadHoldMemo.set : new Set();
  try {
    const row = await db
      .prepare("SELECT value FROM meta WHERE key = ?")
      .bind(LEAD_HOLD_KEY)
      .first();
    if (row && row.value) {
      const parsed = JSON.parse(String(row.value));
      if (Array.isArray(parsed)) {
        set = new Set(parsed.map((x) => {
          if (typeof x === "string") return x;
          if (x && typeof x === "object" && x.path && x.level !== "soft") return String(x.path);
          return null;
        }).filter(Boolean));
      }
    }
  } catch {
    // Fail open to the last known set (empty before the first good
    // read): a registry read fault must never take a listing page down.
  }
  leadHoldMemo = { set, at: now };
  return set;
}

function defaultCache() {
  try {
    if (typeof caches !== "undefined" && caches.default) return caches.default;
  } catch {
    // No Cache API in this runtime: render without caching.
  }
  return null;
}

// Cache key: the full listing URL with the query stripped (listing URLs
// carry no query string; section 2.2) plus the dataset version as the only
// query parameter, so a version bump changes every key at once (2.3).
function cacheKeyFor(url, version) {
  return new Request(`${url.origin}${url.pathname}?__ytpv=${encodeURIComponent(version)}`, {
    method: "GET",
  });
}

async function cacheMatch(cache, key) {
  try {
    return (await cache.match(key)) || null;
  } catch {
    return null; // fail open to a render
  }
}

function cachePut(cache, key, response, ctx) {
  try {
    // A failed or rejected cache write never affects the response served.
    const put = Promise.resolve(cache.put(key, response)).catch(() => {});
    if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(put);
    else return put;
  } catch {
    // Same, for a put that throws synchronously.
  }
  return null;
}

// The stored form of an origin 404: same body and content type, the
// negative-caching Cache-Control above. The client still receives the
// origin's own response untouched on the miss itself.
async function negativeResponse(originRes) {
  const body = await originRes.clone().text();
  const headers = new Headers(originRes.headers);
  headers.set("Cache-Control", NEGATIVE_CACHE_CONTROL);
  return new Response(body, {
    status: 404,
    statusText: originRes.statusText,
    headers,
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const m = LISTING_PATH.exec(url.pathname);
    if (!m) return fetch(request); // not listing-shaped: static origin serves it
    const path = `${m[1]}/${m[2]}`;

    // Cache check first (design section 2.2), ahead of the redirect lookup
    // and the render. Only GET requests engage the cache; the Cache API
    // stores nothing else. Within one dataset version the data cannot
    // change, so a cached page can never shadow a newer redirect or render.
    const cache = request.method === "GET" ? defaultCache() : null;
    let cacheKey = null;
    if (cache) {
      cacheKey = cacheKeyFor(url, await datasetVersion(env.DB));
      const hit = await cacheMatch(cache, cacheKey);
      if (hit) return hit;
    }

    const redirect = await lookupRedirect(env.DB, path);
    if (redirect) {
      return Response.redirect(`https://${url.host}/${redirect.to_path}/`, redirect.status || 301);
    }
    const html = await renderListing(env.DB, path);
    if (html === null) {
      // Unknown slug: pass through (static 404 there), and negative-cache
      // the 404 outcome so repeated probes cost no render and no D1 read.
      const originRes = await fetch(request);
      if (cache && originRes.status === 404) {
        const stored = await negativeResponse(originRes);
        await cachePut(cache, cacheKey, stored, ctx);
      }
      return originRes;
    }
    const response = new Response(html, { headers: LISTING_HEADERS });
    if (cache) await cachePut(cache, cacheKey, response.clone(), ctx);
    return response;
  },
};
